const body = $json.body ?? $json;
const prompt = String(body.prompt ?? body.message ?? '').trim();
if (!prompt) throw new Error('BUYFLOW_EMPTY_TEACHER_MESSAGE');
const history = Array.isArray(body.history) ? body.history.slice(-12).filter((m) => m && ['user','assistant'].includes(m.role) && typeof m.content === 'string') : [];
return [{json:{prompt, history}}];

const response = String($json.message?.content ?? $json.response ?? '').trim();
if (!response) throw new Error('BUYFLOW_EMPTY_TEACHER_RESPONSE');
return [{json:{ok:true,provider:'ollama-local',model:$env.BUYFLOW_OLLAMA_MODEL || 'qwen3:8b',response}}];
